<?php
require_once __DIR__.'/../includes/header.php';
require_once __DIR__.'/../config/database.php';
check_access([1]);$db=Database::getInstance();

$guru_id=(int)($_GET['guru_id']??0);$kelas_id=(int)($_GET['kelas_id']??0);$mapel_id=(int)($_GET['mapel_id']??0);
$semester=in_array($_GET['semester']??'',['Ganjil','Genap'],true)?$_GET['semester']:'';
$tahun_ajaran=trim($_GET['tahun_ajaran']??'');$jenis=in_array($_GET['jenis']??'',['Kuis','UTS','UAS'],true)?$_GET['jenis']:'';
$status_filter=in_array($_GET['status']??'',['terjadwal','aktif','selesai','belum_peserta'],true)?$_GET['status']:'';
$q=trim($_GET['q']??'');$ujian_id=(int)($_GET['ujian_id']??0);$halaman=max(1,(int)($_GET['page']??1));$per_halaman=10;
if(mb_strlen($q)>100)$q=mb_substr($q,0,100);if(mb_strlen($tahun_ajaran)>10)$tahun_ajaran='';
$guru_list=$db->query('SELECT id,nama_lengkap FROM guru ORDER BY nama_lengkap')->fetchAll();
$kelas_list=$db->query('SELECT id,nama_kelas FROM kelas ORDER BY nama_kelas')->fetchAll();
$mapel_list=$db->query('SELECT id,nama_mapel FROM mapel ORDER BY nama_mapel')->fetchAll();
$tahun_list=$db->query('SELECT DISTINCT tahun_ajaran FROM pengajaran ORDER BY tahun_ajaran DESC')->fetchAll(PDO::FETCH_COLUMN);

$where=[];$params=[];
if($guru_id){$where[]='p.guru_id=?';$params[]=$guru_id;}if($kelas_id){$where[]='p.kelas_id=?';$params[]=$kelas_id;}
if($mapel_id){$where[]='p.mapel_id=?';$params[]=$mapel_id;}if($semester!==''){$where[]='p.semester=?';$params[]=$semester;}
if($tahun_ajaran!==''){$where[]='p.tahun_ajaran=?';$params[]=$tahun_ajaran;}if($jenis!==''){$where[]='u.jenis_ujian=?';$params[]=$jenis;}
if($q!==''){$where[]='(u.nama_ujian LIKE ? OR g.nama_lengkap LIKE ? OR m.nama_mapel LIKE ? OR k.nama_kelas LIKE ?)';$cari='%'.$q.'%';array_push($params,$cari,$cari,$cari,$cari);}
$where_sql=$where?' WHERE '.implode(' AND ',$where):'';
$summary_sql="SELECT u.id,u.nama_ujian,u.jenis_ujian,u.durasi_menit,u.waktu_mulai,u.waktu_selesai,u.acak_soal,u.created_at,
 p.semester,p.tahun_ajaran,p.kelas_id,g.nama_lengkap nama_guru,m.nama_mapel,k.nama_kelas,
 (SELECT COUNT(*) FROM soal_ujian so WHERE so.ujian_id=u.id) total_soal,
 (SELECT COUNT(*) FROM soal_ujian so WHERE so.ujian_id=u.id AND so.tipe_soal='PG') soal_pg,
 (SELECT COUNT(*) FROM soal_ujian so WHERE so.ujian_id=u.id AND so.tipe_soal='ESAI') soal_esai,
 (SELECT COUNT(*) FROM siswa s WHERE s.kelas_id=p.kelas_id) total_siswa,
 (SELECT COUNT(*) FROM sesi_ujian su WHERE su.ujian_id=u.id) mulai,
 (SELECT COUNT(*) FROM sesi_ujian su WHERE su.ujian_id=u.id AND su.status='Selesai') peserta_selesai,
 (SELECT COUNT(*) FROM sesi_ujian su WHERE su.ujian_id=u.id AND su.status='Berlangsung') berlangsung,
 (SELECT AVG(nu.nilai_total) FROM nilai_ujian nu WHERE nu.ujian_id=u.id) rata_nilai
 FROM ujian u JOIN pengajaran p ON p.id=u.pengajaran_id JOIN guru g ON g.id=p.guru_id
 JOIN mapel m ON m.id=p.mapel_id JOIN kelas k ON k.id=p.kelas_id $where_sql";
$outer=[];
if($status_filter==='terjadwal')$outer[]='x.waktu_mulai>NOW()';
elseif($status_filter==='aktif')$outer[]='x.waktu_mulai<=NOW() AND x.waktu_selesai>=NOW()';
elseif($status_filter==='selesai')$outer[]='x.waktu_selesai<NOW()';
elseif($status_filter==='belum_peserta')$outer[]='x.mulai=0';
$outer_sql=$outer?' WHERE '.implode(' AND ',$outer):'';
$stmt=$db->prepare("SELECT COUNT(*) FROM ($summary_sql) x $outer_sql");$stmt->execute($params);$total_ujian=(int)$stmt->fetchColumn();
$total_halaman=max(1,(int)ceil($total_ujian/$per_halaman));$halaman=min($halaman,$total_halaman);$offset=($halaman-1)*$per_halaman;
$stmt=$db->prepare("SELECT x.*,GREATEST(x.total_siswa-x.mulai,0) belum_mulai FROM ($summary_sql) x $outer_sql ORDER BY x.waktu_mulai DESC,x.id DESC LIMIT ? OFFSET ?");
$i=1;foreach($params as $param)$stmt->bindValue($i++,$param,PDO::PARAM_STR);$stmt->bindValue($i++,$per_halaman,PDO::PARAM_INT);$stmt->bindValue($i,$offset,PDO::PARAM_INT);$stmt->execute();$ujian_list=$stmt->fetchAll();
$stmt=$db->prepare("SELECT COUNT(*) total,COALESCE(SUM(x.total_soal),0) soal,COALESCE(SUM(x.peserta_selesai),0) selesai,COALESCE(SUM(GREATEST(x.total_siswa-x.mulai,0)),0) belum FROM ($summary_sql) x $outer_sql");$stmt->execute($params);$ringkasan=$stmt->fetch();

$detail_ujian=null;$soal_list=[];$peserta=[];
if($ujian_id){
 $stmt=$db->prepare("SELECT x.*,GREATEST(x.total_siswa-x.mulai,0) belum_mulai FROM ($summary_sql) x WHERE x.id=?");$detail_params=$params;$detail_params[]=$ujian_id;$stmt->execute($detail_params);$detail_ujian=$stmt->fetch();
 if($detail_ujian){
  $stmt=$db->prepare('SELECT id,tipe_soal,pertanyaan,opsi_a,opsi_b,opsi_c,opsi_d,opsi_e,kunci_jawaban,bobot FROM soal_ujian WHERE ujian_id=? ORDER BY id');$stmt->execute([$ujian_id]);$soal_list=$stmt->fetchAll();
  $stmt=$db->prepare("SELECT su.id sesi_id,su.waktu_mulai,su.waktu_selesai,COALESCE(su.status,'Belum Mengerjakan') status,
   s.id siswa_id,s.nisn,s.nis,s.nama_lengkap,
   SUM(CASE WHEN js.id IS NOT NULL AND (js.jawaban_pg IS NOT NULL OR (js.jawaban_esai IS NOT NULL AND TRIM(js.jawaban_esai)<>'')) THEN 1 ELSE 0 END) dijawab,
   COALESCE(nu.nilai_pg,0) nilai_pg,COALESCE(nu.nilai_esai,0) nilai_esai,COALESCE(nu.nilai_total,0) nilai_total
   FROM siswa s LEFT JOIN sesi_ujian su ON su.siswa_id=s.id AND su.ujian_id=?
   LEFT JOIN jawaban_siswa js ON js.sesi_ujian_id=su.id
   LEFT JOIN nilai_ujian nu ON nu.ujian_id=? AND nu.siswa_id=s.id
   WHERE s.kelas_id=? GROUP BY s.id ORDER BY su.status='Berlangsung' DESC,su.status IS NULL DESC,s.nama_lengkap");
  $stmt->execute([$ujian_id,$ujian_id,$detail_ujian['kelas_id']]);$peserta=$stmt->fetchAll();
 }
}
$query_state=['guru_id'=>$guru_id,'kelas_id'=>$kelas_id,'mapel_id'=>$mapel_id,'semester'=>$semester,'tahun_ajaran'=>$tahun_ajaran,'jenis'=>$jenis,'status'=>$status_filter,'q'=>$q];
$filter_aktif=array_filter($query_state,static fn($v)=>$v!==''&&$v!==0);
?>
