<div class="col-6 col-md-3 col-xl"><label class="form-label">Kelas</label><select name="kelas_id" class="form-select"><option value="0">Semua</option><?php foreach($kelas_list as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $kelas_id===(int)$r['id']?'selected':'' ?>><?= sanitize($r['nama_kelas']) ?></option><?php endforeach ?></select></div>
<div class="col-6 col-md-3 col-xl"><label class="form-label">Mapel</label><select name="mapel_id" class="form-select"><option value="0">Semua</option><?php foreach($mapel_list as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $mapel_id===(int)$r['id']?'selected':'' ?>><?= sanitize($r['nama_mapel']) ?></option><?php endforeach ?></select></div>
<div class="col-6 col-md-3 col-xl"><label class="form-label">Semester</label><select name="semester" class="form-select"><option value="">Semua</option><option <?= $semester==='Ganjil'?'selected':'' ?>>Ganjil</option><option <?= $semester==='Genap'?'selected':'' ?>>Genap</option></select></div>
<div class="col-6 col-md-3 col-xl"><label class="form-label">Tahun</label><select name="tahun_ajaran" class="form-select"><option value="">Semua</option><?php foreach($tahun_list as $r): ?><option value="<?= sanitize($r) ?>" <?= $tahun_ajaran===$r?'selected':'' ?>><?= sanitize($r) ?></option><?php endforeach ?></select></div>
<div class="col-6 col-md-3 col-xl"><label class="form-label">Jenis</label><select name="jenis" class="form-select"><option value="">Semua</option><?php foreach(['Kuis','UTS','UAS'] as $r): ?><option value="<?= $r ?>" <?= $jenis===$r?'selected':'' ?>><?= $r ?></option><?php endforeach ?></select></div>
<div class="col-6 col-md-3 col-xl"><label class="form-label">Status</label><select name="status" class="form-select"><option value="">Semua</option><option value="terjadwal" <?= $status_filter==='terjadwal'?'selected':'' ?>>Terjadwal</option><option value="aktif" <?= $status_filter==='aktif'?'selected':'' ?>>Sedang Aktif</option><option value="selesai" <?= $status_filter==='selesai'?'selected':'' ?>>Waktu Selesai</option><option value="belum_peserta" <?= $status_filter==='belum_peserta'?'selected':'' ?>>Belum Ada Peserta</option></select></div>
<div class="col-6 col-xl-auto"><button class="btn btn-primary w-100"><i class="fa-solid fa-filter me-1"></i>Terapkan</button></div><?php if($filter_aktif): ?><div class="col-6 col-xl-auto"><a href="monitoring_ujian.php" class="btn btn-light border w-100">Reset</a></div><?php endif ?>
</form></div></section>
<?php if($detail_ujian): ?><section id="detailUjian" class="card exam-card detail-anchor mb-3"><div class="card-body p-3 p-md-4"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><div><h6 class="fw-bold mb-1"><?= sanitize($detail_ujian['nama_ujian']) ?> <span class="badge bg-primary"><?= sanitize($detail_ujian['jenis_ujian']) ?></span></h6><small class="text-muted"><?= sanitize($detail_ujian['nama_mapel']) ?> · <?= sanitize($detail_ujian['nama_kelas']) ?> · <?= sanitize($detail_ujian['nama_guru']) ?></small></div><a href="?<?= http_build_query($query_state) ?>" class="btn btn-sm btn-light border align-self-start"><i class="fa-solid fa-xmark me-1"></i>Tutup Detail</a></div>
<ul class="nav nav-pills mb-3" role="tablist"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#tabPeserta" type="button">Peserta (<?= count($peserta) ?>)</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#tabSoal" type="button">Soal (<?= count($soal_list) ?>)</button></li></ul>
<div class="tab-content"><div class="tab-pane fade show active" id="tabPeserta"><div class="table-responsive d-none d-md-block"><table class="table exam-table table-hover"><thead class="table-light"><tr><th>Siswa</th><th>Status</th><th>Jawaban</th><th>Waktu</th><th>Nilai PG</th><th>Nilai Esai</th><th>Total</th></tr></thead><tbody>
<?php foreach($peserta as $p): $mulai=!empty($p['sesi_id']);$kelas_status=$p['status']==='Selesai'?'bg-success':($p['status']==='Berlangsung'?'bg-warning text-dark':'bg-secondary'); ?><tr><td><strong><?= sanitize($p['nama_lengkap']) ?></strong><br><small class="text-muted"><?= sanitize($p['nisn']?:$p['nis']) ?></small></td><td><span class="badge <?= $kelas_status ?>"><?= sanitize($p['status']) ?></span></td><td><?= $mulai?(int)$p['dijawab'].' / '.count($soal_list):'—' ?></td><td><small><?= $mulai?'Mulai: '.date('d/m/Y H:i',strtotime($p['waktu_mulai'])):'Belum membuka ulangan' ?><?php if($mulai): ?><br>Selesai: <?= $p['waktu_selesai']?date('d/m/Y H:i',strtotime($p['waktu_selesai'])):'-' ?><?php endif ?></small></td><td><?= $mulai?number_format((float)$p['nilai_pg'],2,',','.'):'—' ?></td><td><?= $mulai?number_format((float)$p['nilai_esai'],2,',','.'):'—' ?></td><td><?= $mulai?'<strong class="text-primary">'.number_format((float)$p['nilai_total'],2,',','.').'</strong>':'—' ?></td></tr><?php endforeach ?></tbody></table></div>
<div class="d-md-none"><?php foreach($peserta as $p): $mulai=!empty($p['sesi_id']);$kelas_status=$p['status']==='Selesai'?'bg-success':($p['status']==='Berlangsung'?'bg-warning text-dark':'bg-secondary'); ?><article class="participant-mobile"><div class="d-flex justify-content-between gap-2"><strong><?= sanitize($p['nama_lengkap']) ?></strong><span class="badge <?= $kelas_status ?>"><?= sanitize($p['status']) ?></span></div><?php if($mulai): ?><small class="text-muted">Jawaban <?= (int)$p['dijawab'] ?>/<?= count($soal_list) ?></small><div class="row mt-2 small"><div class="col">PG <strong><?= number_format((float)$p['nilai_pg'],2,',','.') ?></strong></div><div class="col">Esai <strong><?= number_format((float)$p['nilai_esai'],2,',','.') ?></strong></div><div class="col">Total <strong class="text-primary"><?= number_format((float)$p['nilai_total'],2,',','.') ?></strong></div></div><?php else: ?><small class="text-muted">Belum membuka ulangan</small><?php endif ?></article><?php endforeach ?></div></div>
<div class="tab-pane fade" id="tabSoal"><?php foreach($soal_list as $index=>$soal): ?><article class="question-item"><div class="d-flex justify-content-between gap-2 mb-2"><span class="badge bg-primary">Soal <?= $index+1 ?> · <?= sanitize($soal['tipe_soal']) ?></span><small class="text-muted">Bobot <?= (int)$soal['bobot'] ?></small></div><div class="mb-3"><?= nl2br(sanitize($soal['pertanyaan'])) ?></div><?php if($soal['tipe_soal']==='PG'): ?><div class="option-list"><?php foreach(['A','B','C','D','E'] as $opsi): $teks=$soal['opsi_'.strtolower($opsi)];if(!$teks)continue; ?><div class="option-item <?= $soal['kunci_jawaban']===$opsi?'bg-success-subtle text-success fw-semibold':'' ?>"><?= $opsi ?>. <?= sanitize($teks) ?><?= $soal['kunci_jawaban']===$opsi?' · Kunci':'' ?></div><?php endforeach ?></div><?php else: ?><span class="badge bg-light text-dark">Jawaban dinilai manual oleh guru</span><?php endif ?></article><?php endforeach ?><?php if(!$soal_list): ?><div class="text-center text-muted py-4">Belum ada soal pada ulangan ini.</div><?php endif ?></div></div>
</div></section><?php elseif($ujian_id): ?><div class="alert alert-danger">Ulangan tidak ditemukan pada filter yang dipilih.</div><?php endif ?>
