<?php foreach($ujian_list as $u): $sekarang=time();$status_waktu=strtotime($u['waktu_mulai'])>$sekarang?'Terjadwal':(strtotime($u['waktu_selesai'])<$sekarang?'Selesai':'Aktif');$warna=$status_waktu==='Aktif'?'success':($status_waktu==='Terjadwal'?'primary':'secondary'); ?><tr><td class="ps-4"><strong><?= sanitize($u['nama_ujian']) ?></strong><br><span class="badge bg-light text-dark"><?= sanitize($u['jenis_ujian']) ?></span> <small><?= (int)$u['durasi_menit'] ?> menit</small></td><td><strong><?= sanitize($u['nama_mapel']) ?></strong><br><small class="text-muted"><?= sanitize($u['nama_kelas']) ?> · <?= sanitize($u['nama_guru']) ?><br><?= sanitize($u['semester']) ?> <?= sanitize($u['tahun_ajaran']) ?></small></td><td><span class="badge bg-<?= $warna ?>"><?= $status_waktu ?></span><br><small><?= date('d/m/Y H:i',strtotime($u['waktu_mulai'])) ?><br><?= date('d/m/Y H:i',strtotime($u['waktu_selesai'])) ?></small></td><td><strong><?= (int)$u['total_soal'] ?></strong><br><small>PG <?= (int)$u['soal_pg'] ?> · Esai <?= (int)$u['soal_esai'] ?></small></td><td><strong><?= (int)$u['mulai'] ?>/<?= (int)$u['total_siswa'] ?></strong> mulai<br><small class="text-success"><?= (int)$u['peserta_selesai'] ?> selesai</small> · <small class="text-warning"><?= (int)$u['berlangsung'] ?> berlangsung</small><br><small class="text-danger"><?= (int)$u['belum_mulai'] ?> belum</small></td><td><?= $u['rata_nilai']!==null?'<strong>'.number_format((float)$u['rata_nilai'],2,',','.').'</strong>':'—' ?></td><td><a href="?<?= http_build_query(array_merge($query_state,['page'=>$halaman,'ujian_id'=>(int)$u['id']])) ?>#detailUjian" class="btn btn-sm btn-primary text-nowrap"><i class="fa-solid fa-eye me-1"></i>Detail</a></td></tr><?php endforeach ?><?php if(!$ujian_list): ?><tr><td colspan="7" class="text-center text-muted py-5">Tidak ada ulangan sesuai filter.</td></tr><?php endif ?></tbody></table></div>
<?php if($total_halaman>1): ?><nav class="p-3 border-top"><ul class="pagination pagination-sm justify-content-center mb-0"><li class="page-item <?= $halaman<=1?'disabled':'' ?>"><a class="page-link" href="?<?= http_build_query(array_merge($query_state,['page'=>max(1,$halaman-1)])) ?>">&laquo;</a></li><?php for($n=max(1,$halaman-2);$n<=min($total_halaman,$halaman+2);$n++): ?><li class="page-item <?= $n===$halaman?'active':'' ?>"><a class="page-link" href="?<?= http_build_query(array_merge($query_state,['page'=>$n])) ?>"><?= $n ?></a></li><?php endfor ?><li class="page-item <?= $halaman>=$total_halaman?'disabled':'' ?>"><a class="page-link" href="?<?= http_build_query(array_merge($query_state,['page'=>min($total_halaman,$halaman+1)])) ?>">&raquo;</a></li></ul></nav><?php endif ?>
</div></section></main></div>
